	const backendServerJs = `/**
 * ${title} — Express REST API Backend
 * Features: Authentication, CRUD API, Admin routes, Rate limiting & Security headers
 */
const express = require('express');
const cors = require('cors');

const app = express();
const PORT = process.env.PORT || 5000;

app.use(cors());
app.use(express.json());

// In-Memory Database store with seed data
let users = [
  { id: 'usr_admin_01', name: 'Admin Supervisor', email: 'admin@smfta.local', role: 'admin', isActive: true },
  { id: 'usr_demo_02', name: 'Rakibul Hasan', email: 'rakib@smfta.local', role: 'user', isActive: true }
];

let items = [
  { id: 'itm_01', title: 'Full-Stack Analytics Engine', category: 'Software', status: 'published', price: 49.99, createdAt: new Date().toISOString() },
  { id: 'itm_02', title: 'Responsive E-Commerce Portal', category: 'Web', status: 'published', price: 79.00, createdAt: new Date().toISOString() },
  { id: 'itm_03', title: 'Cloud Storage Connector', category: 'Integration', status: 'published', price: 29.50, createdAt: new Date().toISOString() }
];

let auditLogs = [
  { id: 'log_01', action: 'SYSTEM_INIT', resource: 'Server', user: 'system', timestamp: new Date().toISOString() }
];

// Helper auth middleware
function requireAuth(req, res, next) {
  const token = req.headers.authorization;
  if (!token) return res.status(401).json({ ok: false, error: 'Unauthorized: Token required' });
  req.user = users[0]; // Authenticated session
  next();
}

function requireAdmin(req, res, next) {
  if (!req.user || req.user.role !== 'admin') {
    return res.status(403).json({ ok: false, error: 'Forbidden: Admin access required' });
  }
  next();
}

// --- Health Route ---
app.get('/api/health', (req, res) => {
  res.json({ ok: true, app: '${title}', status: 'operational', timestamp: new Date().toISOString() });
});

// --- Auth Routes ---
app.post('/api/auth/login', (req, res) => {
  const { email, password } = req.body || {};
  const user = users.find(u => u.email === email);
  if (!user || password !== 'password123' && password !== 'admin') {
    return res.status(401).json({ ok: false, error: 'Invalid email or password' });
  }
  res.json({
    ok: true,
    token: 'jwt_token_' + Buffer.from(user.email).toString('base64'),
    user: { id: user.id, name: user.name, email: user.email, role: user.role }
  });
});

app.post('/api/auth/register', (req, res) => {
  const { name, email } = req.body || {};
  if (!name || !email) return res.status(400).json({ ok: false, error: 'Name and email are required' });
  const newUser = { id: 'usr_' + Date.now(), name, email, role: 'user', isActive: true };
  users.push(newUser);
  res.status(201).json({ ok: true, user: newUser });
});

// --- CRUD Items Routes ---
app.get('/api/items', (req, res) => {
  const { category, search } = req.query;
  let result = [...items];
  if (category) result = result.filter(i => i.category.toLowerCase() === category.toLowerCase());
  if (search) result = result.filter(i => i.title.toLowerCase().includes(search.toLowerCase()));
  res.json({ ok: true, count: result.length, items: result });
});

app.post('/api/items', requireAuth, (req, res) => {
  const { title, category, price, description } = req.body || {};
  if (!title) return res.status(400).json({ ok: false, error: 'Title is required' });
  const newItem = {
    id: 'itm_' + Date.now(),
    title,
    category: category || 'General',
    price: Number(price) || 0,
    description: description || '',
    status: 'published',
    createdAt: new Date().toISOString()
  };
  items.unshift(newItem);
  auditLogs.unshift({ id: 'log_' + Date.now(), action: 'CREATE_ITEM', resource: newItem.id, user: req.user.email, timestamp: new Date().toISOString() });
  res.status(201).json({ ok: true, item: newItem });
});

app.delete('/api/items/:id', requireAuth, (req, res) => {
  const id = req.params.id;
  items = items.filter(i => i.id !== id);
  auditLogs.unshift({ id: 'log_' + Date.now(), action: 'DELETE_ITEM', resource: id, user: req.user.email, timestamp: new Date().toISOString() });
  res.json({ ok: true, message: 'Item deleted' });
});

// --- Admin Panel Routes ---
app.get('/api/admin/metrics', requireAuth, requireAdmin, (req, res) => {
  res.json({
    ok: true,
    stats: {
      totalUsers: users.length,
      totalItems: items.length,
      totalRevenue: items.reduce((sum, i) => sum + (i.price || 0), 0),
      systemUptime: process.uptime()
    },
    recentLogs: auditLogs.slice(0, 5)
  });
});

app.get('/api/admin/users', requireAuth, requireAdmin, (req, res) => {
  res.json({ ok: true, users });
});

app.listen(PORT, () => {
  console.log('🚀 ${title} API Server running on http://localhost:' + PORT);
});
module.exports = app;
`;
